-- =============================================================================
-- Animal Ekarte - Staging Additions
-- PostgreSQL 18
-- 依存: 001_init.sql → 002_seed_master.sql → 003_seed_demo.sql
-- 実行順: 001_init.sql → 002_seed_master.sql → 003_seed_demo.sql → 004_seed_staging.sql
-- 内容: 003_seed_demo.sql に含まれない差分データのみ記載
-- =============================================================================

-- -----------------------------------------------------------------------------
-- permission_group_rules（全グループ・全リソース 144件）
-- 003_seed_demo.sql は ID 省略で INSERT するため auto-assign となり再実行時に
-- シーケンス値がずれる。004 では明示 ID + ON CONFLICT DO UPDATE で冪等性を保証する。
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET
    group_id = EXCLUDED.group_id, resource = EXCLUDED.resource, can_view = EXCLUDED.can_view, can_create = EXCLUDED.can_create, can_edit = EXCLUDED.can_edit, can_delete = EXCLUDED.can_delete,
    updated_at = now();

SELECT setval(pg_get_serial_sequence('permission_group_rules', 'id'), (SELECT MAX(id) FROM permission_group_rules));

-- -----------------------------------------------------------------------------
-- companies（本番: ノア動物病院 id=1 は 003 で挿入済み。ON CONFLICT で冪等）
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name, updated_at = now();

SELECT setval(pg_get_serial_sequence('companies', 'id'), (SELECT MAX(id) FROM companies));

-- -----------------------------------------------------------------------------
-- clinics（本番: 八王子病院=3, 城東センター病院=4, 敷島医院=5）
-- 003_seed_demo では clinic_id=1,2,3 を "八王子病院","城東センター病院","敷島医院" として挿入済み。
-- prodData の id=3 は "八王子病院"（別院）なので ON CONFLICT DO UPDATE で上書き。
-- id=4,5 は新規追加。
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name, company_id = EXCLUDED.company_id, is_active = EXCLUDED.is_active,
    standard_tax_rate = EXCLUDED.standard_tax_rate, reduced_tax_rate = EXCLUDED.reduced_tax_rate,
    updated_at = now();

SELECT setval(pg_get_serial_sequence('clinics', 'id'), (SELECT MAX(id) FROM clinics));

-- -----------------------------------------------------------------------------
-- accounts（本番追加分: id=5..16 は prodData にあり 003 未収録）
-- id=1..4 は 003 で挿入済みのため ON CONFLICT DO NOTHING。
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET
    email = EXCLUDED.email, is_active = EXCLUDED.is_active, is_system_admin = EXCLUDED.is_system_admin,
    updated_at = now();

SELECT setval(pg_get_serial_sequence('accounts', 'id'), (SELECT MAX(id) FROM accounts));

-- -----------------------------------------------------------------------------
-- occupations（新規クリニック用: 城東=4, 敷島別院=5）
-- clinic_id=3 は 003_seed_demo.sql で既に作成（敷島医院）
-- 004 では clinic_id=4,5 のみ追加
-- これらは新しいクリニックのため ID も 13+ に割り当てる
-- ID 衝突を避けるため ON CONFLICT DO NOTHING で重複を許容
ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('occupations', 'id'), (SELECT MAX(id) FROM occupations));

-- -----------------------------------------------------------------------------
-- staffs（本番スタッフ全員: ids 1-35）
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET
    account_id = EXCLUDED.account_id, name = EXCLUDED.name, is_active = EXCLUDED.is_active,
    license_number = EXCLUDED.license_number, occupation_id = EXCLUDED.occupation_id,
    sort_order = EXCLUDED.sort_order, staff_type = EXCLUDED.staff_type,
    reservation_visible = EXCLUDED.reservation_visible, updated_at = now();

SELECT setval(pg_get_serial_sequence('staffs', 'id'), (SELECT MAX(id) FROM staffs));

-- -----------------------------------------------------------------------------
-- permission_groups（clinic_id=4,5 のみ。clinic_id=3 は 003_seed_demo で作成）
-- id=1-6 は 003 で使用（clinic_id=1,2,3 各2グループ）
-- 004 では clinic_id=4,5 用に id=7-10 を割り当て
-- staff_permission_groups も併せて更新済み
-- -----------------------------------------------------------------------------
ON CONFLICT DO NOTHING;

SELECT setval(pg_get_serial_sequence('permission_groups', 'id'), (SELECT MAX(id) FROM permission_groups));

-- -----------------------------------------------------------------------------
-- staff_clinic_assignments（clinic_id=4,5 のみ。clinic_id=3 は 003_seed_demo で作成）
-- スタッフ 1-15（clinic_id=3）の割当は 003 で処理済み
-- 004 では clinic_id=4,5 および デモスタッフ（33-35）を処理
-- -----------------------------------------------------------------------------
ON CONFLICT (id) DO UPDATE SET
    staff_id = EXCLUDED.staff_id, clinic_id = EXCLUDED.clinic_id, is_main = EXCLUDED.is_main,
    updated_at = now();

SELECT setval(pg_get_serial_sequence('staff_clinic_assignments', 'id'), (SELECT MAX(id) FROM staff_clinic_assignments));

-- -----------------------------------------------------------------------------
-- staff_permission_groups（全スタッフ分）
-- -----------------------------------------------------------------------------
ON CONFLICT (staff_id, group_id) DO NOTHING;

