-- -----------------------------------------------------------------------------
-- exam_types（clinic_id=4,5 のみ。clinic_id=3 は 003_seed_demo で作成）
-- clinic_id=4: 5 rows（血液検査、血液化学検査、レントゲン検査、尿検査、エコー）
-- clinic_id=5: 5 rows（血液検査、尿検査、エコー、血液化学検査、レントゲン検査）
-- ID は 1-10 に統一（clinic_id=4 が 1-5、clinic_id=5 が 6-10）
-- exam_type_fields の外部キー参照も併せて更新されている
ON CONFLICT (id) DO UPDATE SET
    clinic_id = EXCLUDED.clinic_id, name = EXCLUDED.name, price = EXCLUDED.price,
    is_active = EXCLUDED.is_active, description = EXCLUDED.description,
    sort_order = EXCLUDED.sort_order, updated_at = now();

SELECT setval(pg_get_serial_sequence('exam_types', 'id'), (SELECT MAX(id) FROM exam_types));

-- -----------------------------------------------------------------------------
-- exam_type_fields（clinic_id=4,5 のみ。ID は exam_types の新 ID に合わせて更新）
-- 旧 exam_type_id: 1-5 (clinic_id=3, 削除) → 未使用
-- 旧 exam_type_id: 6-8, 12-13 (clinic_id=4) → 新 1-5
-- 旧 exam_type_id: 9-11, 14-15 (clinic_id=5) → 新 6-10
ON CONFLICT (id) DO UPDATE SET
    exam_type_id = EXCLUDED.exam_type_id, name = EXCLUDED.name,
    normal_value = EXCLUDED.normal_value, sort_order = EXCLUDED.sort_order, updated_at = now();

SELECT setval(pg_get_serial_sequence('exam_type_fields', 'id'), (SELECT MAX(id) FROM exam_type_fields));

